  'hub.p.party': 'ನೀವು ಬಿಲ್ ಕೊಡುವ ಅಥವಾ ಖರೀದಿಸುವ ಜನರು ಮತ್ತು ಸಂಸ್ಥೆಗಳು. ಯಾವುದೇ ಟೂಲ್‌ನಲ್ಲಿ ಹೆಸರು ಟೈಪ್ ಮಾಡಿ ಆರಿಸಿದರೆ ವಿಳಾಸ, ರಾಜ್ಯ ಮತ್ತು GSTIN ತುಂಬುತ್ತವೆ.',
  'hub.p.item': 'ಸಾಮಾನು ಮತ್ತು ಸರ್ವಿಸ್, ಅವುಗಳ HSN/SAC ಕೋಡ್, ಯೂನಿಟ್, ರೇಟ್ ಮತ್ತು GST ಜೊತೆಗೆ. ಯಾವುದೇ ಟೂಲ್‌ನಲ್ಲಿ ಆರಿಸಿದರೆ ಸಾಲು ತುಂಬುತ್ತದೆ.',
  'hub.p.doc': 'ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಸೇವ್ ಮಾಡಿದ ಪ್ರತಿ ಡಾಕ್ಯುಮೆಂಟ್. ತೆರೆಯುವುದು, ಕಾಪಿ ಮಾಡುವುದು ಅಥವಾ ಪೇಯ್ಡ್ ಎಂದು ಗುರುತಿಸುವುದು ಅದನ್ನು ಮಾಡಿದ ಟೂಲ್‌ನಲ್ಲೇ ಮಾಡಿ.',
