  "hub.rg.sez": "SEZ ಯೂನಿಟ್",
  "v.b2c": "GSTIN ಇಲ್ಲದ ಕಸ್ಟಮರ್‌ಗೆ ₹50,000 ಅಥವಾ ಹೆಚ್ಚಿನ ಬಿಲ್‌ಗೆ GST ನಿಯಮದಂತೆ ಕಸ್ಟಮರ್ ಹೆಸರು, ವಿಳಾಸ ಮತ್ತು ರಾಜ್ಯ ಬೇಕು.",
  "c.r28": "1 ಫೆಬ್ರವರಿ 2026 ರಿಂದ 28% GST ತೆಗೆಯಲಾಗಿದೆ (ಆ ವಸ್ತುಗಳು ಈಗ 40% ಅಥವಾ 18%). ಆದರೂ 28% ಜೊತೆ ಸೇವ್ ಮಾಡಬೇಕೇ?",
  "c.cash2l": "ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ಕಾನೂನಿನಂತೆ ಒಂದು ಬಿಲ್‌ಗೆ ₹2 ಲಕ್ಷ ಅಥವಾ ಹೆಚ್ಚು ನಗದು ತೆಗೆದುಕೊಳ್ಳುವಂತಿಲ್ಲ (ಅಷ್ಟೇ ಮೊತ್ತದ ದಂಡ). ಆದರೂ ಸೇವ್ ಮಾಡಬೇಕೇ?",
  /* Phase 1 additions */
  "v.orig": "ಈ ನೋಟ್ ಯಾವ ಇನ್‌ವಾಯ್ಸ್‌ಗಾಗಿ ಎಂದು ಅದರ ನಂಬರ್ ಮತ್ತು ದಿನಾಂಕ ಟೈಪ್ ಮಾಡಿ. GST ನಿಯಮದಂತೆ ನೋಟ್‌ನಲ್ಲಿ ಅವು ಇರಬೇಕು.",
  "v.naddr": "GSTIN ಇಲ್ಲದ ಖರೀದಿದಾರರಿಗೆ, ಅವರ ವಿಳಾಸ ಮತ್ತು ರಾಜ್ಯ ಟೈಪ್ ಮಾಡಿ.",
  "c.cn30": "ಈ ಕ್ರೆಡಿಟ್ ನೋಟ್‌ನ ದಿನಾಂಕ, ಆ ಇನ್‌ವಾಯ್ಸ್‌ನ ಹಣಕಾಸು ವರ್ಷ ಮುಗಿದ ನಂತರದ 30 ನವೆಂಬರ್‌ನ ನಂತರ ಇದೆ (ಅಥವಾ ಆ ವರ್ಷದ ವಾರ್ಷಿಕ ರಿಟರ್ನ್ ಅದಕ್ಕಿಂತ ಮೊದಲೇ ಫೈಲ್ ಮಾಡಿದ್ದರೆ, ಅದರ ನಂತರ). ಆ ದಿನಾಂಕದ ನಂತರ ಅದರ ಮೇಲಿನ GST ಕಡಿಮೆ ಮಾಡಲು ಆಗುವುದಿಲ್ಲ (ಬಿಸಿನೆಸ್ ಡಾಕ್ಯುಮೆಂಟ್ ಆಗಿ ನೋಟ್ ಮಾನ್ಯ). ಆದರೂ ಸೇವ್ ಮಾಡಬೇಕೇ?",
  "s.tds": "ಹಣ ಕೊಟ್ಟವರು ಕಡಿತ ಮಾಡಿದ TDS (₹)",
  "s.h.tds": "ಹಣ ಕೊಟ್ಟವರು TDS ಕಡಿತ ಮಾಡಿದ್ದರೆ ಮಾತ್ರ. ರಸೀದಿಯಲ್ಲಿ TDS ಮತ್ತು ಸೆಟಲ್ ಆದ ಪೂರ್ತಿ ಬಿಲ್ ಮೊತ್ತ ಕಾಣುತ್ತದೆ.",
  "c.cash10k": "ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ಕಾನೂನಿನಂತೆ ಒಬ್ಬ ವ್ಯಕ್ತಿಗೆ ಒಂದು ದಿನದಲ್ಲಿ ₹10,000 ಕ್ಕಿಂತ ಹೆಚ್ಚು ನಗದು ಪಾವತಿ ಬಿಸಿನೆಸ್ ಖರ್ಚಾಗಿ ಒಪ್ಪಿಗೆಯಾಗುವುದಿಲ್ಲ (ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್‌ಗಳಿಗೆ ₹35,000). ಆದರೂ ಸೇವ್ ಮಾಡಬೇಕೇ?",
