  "s.r.new": "ಹೊಸ ರೆಜಿಮ್ (ಡೀಫಾಲ್ಟ್)",
  "s.r.old": "ಹಳೆಯ ರೆಜಿಮ್",
  "s.ptstate": "ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್‌ಗೆ ರಾಜ್ಯ",
  "s.pt.none": "ರಾಜ್ಯ ಆಯ್ಕೆ ಮಾಡಿ",
  "s.pt.manual": "ಈ ರಾಜ್ಯದ ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್ ಇನ್ನೂ ನಮ್ಮ ಟೇಬಲ್‌ನಲ್ಲಿ ಇಲ್ಲ. ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್ ಸಾಲಿನಲ್ಲಿ ಟೈಪ್ ಮಾಡಿ.",
  "s.pfbtn2": "PF, ESI, ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್ ಮತ್ತು TDS ಲೆಕ್ಕ ಹಾಕಿ",
  "s.h.pf2": "PF: ಬೇಸಿಕ್‌ನ 12% (₹25,000 ವರೆಗಿನ ಬೇಸಿಕ್ ಮೇಲೆ); ESI: ಗ್ರಾಸ್ ₹21,000 ಅಥವಾ ಕಡಿಮೆ ಇದ್ದಾಗ 0.75%; ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್: ಮೇಲೆ ಆಯ್ಕೆ ಮಾಡಿದ ರಾಜ್ಯದಿಂದ; TDS: ಈ ತಿಂಗಳ ಗ್ರಾಸ್ × 12, FY 2026-27 ಸ್ಲ್ಯಾಬ್‌ಗಳು ಮತ್ತು ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಡಿಡಕ್ಷನ್‌ನೊಂದಿಗೆ. ನಿಮ್ಮ ನಿಯಮಗಳ ಜೊತೆ ಪರಿಶೀಲಿಸಿ.",
  "s.w.wages": "ಬೇಸಿಕ್ ಸಂಬಳ ಗ್ರಾಸ್‌ನ ಅರ್ಧಕ್ಕಿಂತ ಕಡಿಮೆ. ಲೇಬರ್ ಕೋಡ್‌ಗಳಂತೆ ಹೆಚ್ಚುವರಿ ಅಲೋವೆನ್ಸ್‌ಗಳು PF ಮತ್ತು ಗ್ರಾಚ್ಯುಟಿಗೆ ವೇತನವಾಗಿ ಲೆಕ್ಕಕ್ಕೆ ಬರುತ್ತವೆ.",
  /* GSTIN details from the GST portal */
