  "app.local": "ಡೇಟಾ ಹೋಮ್ ತೆರೆಯಲಿಲ್ಲ, ಆದ್ದರಿಂದ ಈ ಸೈಟ್‌ನಲ್ಲಿ ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಸೇವ್ ಆಗಿದೆ. ಮುಂದಿನ ಸಲ ಡೇಟಾ ಹೋಮ್‌ಗೆ ಹೋಗುತ್ತದೆ.",
  "app.vault": "ಈ ಬ್ರೌಸರ್‌ನ ಡೇಟಾ ಹೋಮ್‌ನಲ್ಲಿ ಸೇವ್ ಆಗಿದೆ, ಇದು Nivesh Sahayak ನ ಎಲ್ಲ ಟೂಲ್‌ಗಳಿಗೆ ಹಂಚಿಕೆಯಾಗಿದೆ. ನಮಗೆ ಏನೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.",
  "app.help": "ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
  "app.helpp": "billing., cash-memo. ಮತ್ತು credit-note. ನಲ್ಲಿ ಮಾಡಿದ ಬಿಲ್‌ಗಳು ಇಲ್ಲಿ ತಾನಾಗಿ ಕಾಣುತ್ತವೆ. ಬಂದ ಮತ್ತು ಕೊಟ್ಟ ಹಣವನ್ನು ಇಲ್ಲಿ ಬರೆಯಿರಿ; ಆಪ್ ಅದನ್ನು ಬಿಲ್‌ಗಳಿಗೆ ಜೋಡಿಸುತ್ತದೆ, ಅಡ್ವಾನ್ಸ್ ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ, ಬಾಕಿ ಮತ್ತು ಕೈಯಲ್ಲಿನ ಕ್ಯಾಶ್ ಲೆಕ್ಕ ಹಾಕುತ್ತದೆ.",
