  "g1.w.irn": "ಬಿಲ್ {no} ಗೆ ಇ-ಇನ್‌ವಾಯ್ಸ್ IRN ಇದೆ: ಪೋರ್ಟಲ್ ಅದನ್ನು ಈಗಾಗಲೇ GSTR-1ನಲ್ಲಿ ಸೇರಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ಅಲ್ಲಿ ಪರಿಶೀಲಿಸಿ, ಎರಡು ಬಾರಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಡಿ.",
  "g1.w.gap": "“{s}” ನಂಬರ್ ಸರಣಿಯಲ್ಲಿ {n} ನಂಬರ್(ಗಳು) ಬಿಟ್ಟುಹೋಗಿವೆ. ಅವನ್ನು ಟೇಬಲ್ 13ರಲ್ಲಿ ರದ್ದಾದವು ಎಂದು ಎಣಿಸಲಾಗುತ್ತದೆ; ಬೇರೆ ತಿಂಗಳಲ್ಲಿ ನೀಡಿದ್ದರೆ ಬದಲಿಸಿ.",
