  "bk.h.s2": "ಒಂದು ಐಟಂಗೆ ಒಂದು ಸಾಲು. ಒಂದೇ ಇನ್‌ವಾಯ್ಸ್ ನಂಬರ್ ಇರುವ ಸಾಲುಗಳು ಸೇರಿ ಒಂದು ಇನ್‌ವಾಯ್ಸ್ ಆಗುತ್ತವೆ. ನಿಮ್ಮದೇ ಶೀಟ್‌ನ ಹೆಡ್ಡಿಂಗ್‌ಗಳು ನಮ್ಮದರಂತೆ ಇದ್ದರೆ ಅದೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ.",
  "bk.h.s2e": "ಒಂದು ಐಟಂಗೆ ಒಂದು ಸಾಲು. ಒಂದೇ ಡಾಕ್ಯುಮೆಂಟ್ ನಂಬರ್ ಇರುವ ಸಾಲುಗಳು ಸೇರಿ ಒಂದು ಇ-ವೇ ಬಿಲ್ ಆಗುತ್ತವೆ. ವಾಹನವನ್ನು ಖಾಲಿ ಬಿಟ್ಟರೆ Part A ಮಾತ್ರ ಆಗುತ್ತದೆ; ವಾಹನವನ್ನು ನಂತರ ಸೇರಿಸಬಹುದು.",
