  "bk.badfile": "ಈ ಫೈಲ್ ಓದಲು ಆಗಲಿಲ್ಲ. .xlsx ಅಥವಾ .csv ಫೈಲ್ ಆಯ್ಕೆಮಾಡಿ.",
