  "bk.made": "{file} ನಿಮ್ಮ ಡೌನ್‌ಲೋಡ್ಸ್‌ನಲ್ಲಿ ಸೇವ್ ಆಯಿತು (ಇನ್‌ವಾಯ್ಸ್‌ಗಳು: {n}). ಇದನ್ನು ಇ-ಇನ್‌ವಾಯ್ಸ್ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.",
