  "bk.zero": "ಡಾಕ್ಯುಮೆಂಟ್ ವಿಧ {v} ಆದರೆ ಪ್ರತಿ ಐಟಂಗೂ GST 0% ಇರಬೇಕು.",
  "bk.s3": "ಪೋರ್ಟಲ್‌ನ ಉತ್ತರವನ್ನು ಲೋಡ್ ಮಾಡಿ",
  "bk.h.s3": "ಅಪ್‌ಲೋಡ್ ಆದ ಮೇಲೆ, ಪೋರ್ಟಲ್‌ನಿಂದ ರಿಸಲ್ಟ್ (JSON ಅಥವಾ Excel) ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಇಲ್ಲಿ ಆಯ್ಕೆಮಾಡಿ. IRN, Ack ಸಂಖ್ಯೆ, ಸಹಿ ಮಾಡಿದ QR ಕೋಡ್ ಪ್ರತಿ ಸೇವ್ ಮಾಡಿದ ಇನ್‌ವಾಯ್ಸ್‌ಗೆ ಸೇರುತ್ತವೆ, ಪ್ರಿಂಟ್‌ಗೆ ರೆಡಿಯಾಗಿ.",
  "bk.h.s3e": "ಜನರೇಟ್ ಮಾಡಿದ ಮೇಲೆ, ಪೋರ್ಟಲ್‌ನಿಂದ ರಿಸಲ್ಟ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಇಲ್ಲಿ ಆಯ್ಕೆಮಾಡಿ. ಇ-ವೇ ಬಿಲ್ ಸಂಖ್ಯೆಗಳು ಸೇವ್ ಮಾಡಿದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಿಗೂ, ಕೆಳಗಿನ ವಾಹನ ಫೈಲ್‌ಗೂ ಸೇರುತ್ತವೆ.",
  "bk.got": "ಉತ್ತರದಲ್ಲಿ ಸಿಕ್ಕಿದ್ದು: {n}. ಸೇವ್ ಮಾಡಿದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಿಗೆ ಹೊಂದಿದ್ದು: {k}.",
  "bk.open": "ತೆರೆದು ಪ್ರಿಂಟ್ ಮಾಡಿ",
  "bk.notsaved": "ಇಲ್ಲಿ ಸೇವ್ ಆಗಿಲ್ಲ",
  "bk.h.notsaved": "ಕೆಲವು ಸಂಖ್ಯೆಗಳು ಸೇವ್ ಮಾಡಿದ ಇನ್‌ವಾಯ್ಸ್‌ಗೆ ಹೊಂದಲಿಲ್ಲ. ಮೊದಲು ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಸೇವ್ ಮಾಡಿ (ಮೇಲೆ ಟಿಕ್ ಮಾಡಿ, ಅಥವಾ ಬಿಲ್ಲಿಂಗ್ ಮೇಕರ್‌ನಲ್ಲಿ ಮಾಡಿ), ನಂತರ ಉತ್ತರವನ್ನು ಮತ್ತೆ ಲೋಡ್ ಮಾಡಿ.",
  "bk.pb": "ವಾಹನವನ್ನು ನಂತರ ಸೇರಿಸಿ (Part B)",
