  "g3.p.cf": "ಮುಂದಿನ ಅವಧಿಗೆ ಉಳಿದ ಕ್ರೆಡಿಟ್",
  "g3.note": "CGST ಕಾಯ್ದೆಯ ಸೆಕ್ಷನ್ 49 ಮತ್ತು ನಿಯಮ 88A ಪ್ರಕಾರ ಸೆಟ್-ಆಫ್: ಮೊದಲು IGST ಕ್ರೆಡಿಟ್ ಬಳಸಲಾಗುತ್ತದೆ, ನಂತರ CGST ಮತ್ತು SGST/UTGST ಕ್ರೆಡಿಟ್; CGST ಮತ್ತು SGST ಕ್ರೆಡಿಟ್‌ಗಳು ಒಂದಕ್ಕೊಂದು ವಿರುದ್ಧ ಬಳಕೆಯಾಗುವುದಿಲ್ಲ; ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಟ್ಯಾಕ್ಸ್ ಕ್ಯಾಶ್‌ನಲ್ಲೇ ಕಟ್ಟಬೇಕು. ನೀವು ಫೈಲ್ ಮಾಡಿದಾಗ ಪೋರ್ಟಲ್ ಅಂತಿಮ ಸೆಟ್-ಆಫ್ ಮಾಡುತ್ತದೆ.",
  "g3.w.zr": "ಬಿಲ್ {no} ರಫ್ತು ಅಥವಾ SEZ ಬಿಲ್, ಆದರೆ CGST/SGST ತೋರಿಸಿದೆ. Zero rated ಪೂರೈಕೆಗಳಲ್ಲಿ IGST ಮಾತ್ರ ಇರುತ್ತದೆ.",
  "g3.w.rcmv": "ವೋಚರ್ {no}: ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಟ್ಯಾಕ್ಸ್ ಅನ್ನು CGST + SGST ಎಂದು ತೆಗೆದುಕೊಳ್ಳಲಾಗಿದೆ. ಸಪ್ಲೈಯರ್ ಬೇರೆ ರಾಜ್ಯದವರಾದರೆ (IGST) ಬಾಕ್ಸ್‌ಗಳನ್ನು ಬದಲಿಸಿ.",
  "g3.w.nogstin": "{p} ರ ಖರೀದಿ ಬಿಲ್ {no} ಗೆ ಸರಿಯಾದ ಸಪ್ಲೈಯರ್ GSTIN ಇಲ್ಲ, ಆದ್ದರಿಂದ ಅದರ ITC GSTR-2B ನಲ್ಲಿ ಕಾಣುವುದಿಲ್ಲ.",
  "g3.w.2b": "ಬಾಕ್ಸ್ 4(A)(5) ನ ITC ನಿಮ್ಮ ಸೇವ್ ಮಾಡಿದ ಖರೀದಿ ಬಿಲ್‌ಗಳು ಮತ್ತು ಖರ್ಚುಗಳಿಂದ ಬಂದಿದೆ. ನಿಮ್ಮ GSTR-2B ನಲ್ಲಿ ಕಾಣುವುದನ್ನು ಮಾತ್ರ ಕ್ಲೈಮ್ ಮಾಡಿ; GSTR-2B ಅಂಕಿ ಕಡಿಮೆ ಇದ್ದರೆ ಅದನ್ನೇ ಟೈಪ್ ಮಾಡಿ.",
  "g3.w.neg": "ಲಭ್ಯ ಕ್ರೆಡಿಟ್ ಸೊನ್ನೆಗಿಂತ ಕಡಿಮೆ ಇದೆ: ರಿವರ್ಸಲ್‌ಗಳು ಕ್ರೆಡಿಟ್‌ಗಿಂತ ಹೆಚ್ಚು. ವ್ಯತ್ಯಾಸವನ್ನು ಕ್ಯಾಶ್‌ನಲ್ಲಿ ಕಟ್ಟಬೇಕು; ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ರನ್ನು ಕೇಳಿ.",
  /* gstr2b */
