  "g2.loaded": "ಈ ಬ್ರೌಸರ್‌ನ ಡೇಟಾ ಹೋಮ್‌ನಲ್ಲಿ {n} ಖರೀದಿ ಬಿಲ್‌ಗಳು ಸಿಕ್ಕಿವೆ.",
