  "g2.empty": "ಈ ಫೈಲ್‌ನಲ್ಲಿ ಬಿಲ್‌ಗಳು ಸಿಗಲಿಲ್ಲ. GST ಪೋರ್ಟಲ್‌ನಿಂದ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ GSTR-2B JSON ಅಥವಾ Excel ತೆರೆಯಿರಿ.",
