  "g2.s.onlybooks": "ನಿಮ್ಮ ಖರೀದಿ ಬಿಲ್‌ಗಳಲ್ಲಿ ಇದೆ, GSTR-2B ನಲ್ಲಿ ಇಲ್ಲ",
  "g2.s.noitc": "GSTR-2B ಹೇಳುತ್ತದೆ: ITC ಲಭ್ಯವಿಲ್ಲ",
  "g2.s.nofile": "ಈ GSTR-2B ನಲ್ಲಿ ಏನೂ ಇಲ್ಲದ ಸಪ್ಲೈಯರ್‌ಗಳು",
  "g2.h.ok": "ಅದೇ ಸಪ್ಲೈಯರ್, ನಂಬರ್, ಮೊತ್ತ ಮತ್ತು ದಿನಾಂಕ. ಈ ಕ್ರೆಡಿಟ್ ಕ್ಲೈಮ್ ಮಾಡಬಹುದು.",
  "g2.h.diff": "ಎರಡರಲ್ಲೂ ಇದೆ, ಆದರೆ ಅಂಕಿಗಳು ಬೇರೆ. ಸಪ್ಲೈಯರ್ ಜೊತೆ ಬಿಲ್ ಪರಿಶೀಲಿಸಿ; GSTR-2B ನಲ್ಲಿ ಕಾಣುವುದನ್ನು ಮಾತ್ರ ಕ್ಲೈಮ್ ಮಾಡಿ.",
  "g2.h.numdiff": "ಅದೇ ಸಪ್ಲೈಯರ್ ಮತ್ತು ಮೊತ್ತ, ಆದರೆ ಬಿಲ್ ನಂಬರ್ ಬೇರೆ ರೀತಿ ಬರೆದಿದೆ. ಸಾಮಾನ್ಯವಾಗಿ ಟೈಪಿಂಗ್ ವ್ಯತ್ಯಾಸ: ನಿಮ್ಮ ಎಂಟ್ರಿ ಸರಿಪಡಿಸಿ.",
  "g2.h.only2b": "ಸಪ್ಲೈಯರ್ ಈ ಬಿಲ್‌ಗಳನ್ನು ರಿಪೋರ್ಟ್ ಮಾಡಿದ್ದಾರೆ, ಆದರೆ ಅವು ನಿಮ್ಮ ಪುಸ್ತಕದಲ್ಲಿ ಸೇವ್ ಆಗಿಲ್ಲ. ಸರಕು ಅಥವಾ ಸೇವೆ ಸಿಕ್ಕಿದ್ದರೆ ಎಂಟ್ರಿ ಮಾಡಿ, ಇಲ್ಲದಿದ್ದರೆ ಸಪ್ಲೈಯರ್‌ಗೆ ಸರಿಪಡಿಸಲು ಹೇಳಿ.",
  "g2.h.onlybooks": "ಈ ದಿನಾಂಕಗಳ ನಿಮ್ಮ ಬಿಲ್‌ಗಳನ್ನು ಸಪ್ಲೈಯರ್ ಇನ್ನೂ ರಿಪೋರ್ಟ್ ಮಾಡಿಲ್ಲ. GSTR-2B ನಲ್ಲಿ ಬರುವವರೆಗೆ ITC ಕ್ಲೈಮ್ ಮಾಡಬೇಡಿ; ಸಪ್ಲೈಯರ್‌ಗೆ ನೆನಪಿಸಿ.",
  "g2.h.noitc": "ಪೋರ್ಟಲ್ ITC ಲಭ್ಯವಿಲ್ಲ ಎಂದು ತೋರಿಸುವ ಬಿಲ್‌ಗಳು (ಉದಾಹರಣೆಗೆ ಪ್ಲೇಸ್ ಆಫ್ ಸಪ್ಲೈ ಸಪ್ಲೈಯರ್‌ನ ರಾಜ್ಯದಲ್ಲಿರುವುದು, ಅಥವಾ ಸಮಯದ ಮಿತಿ).",
  "g2.h.nofile": "ಈ ಅವಧಿಯಲ್ಲಿ ಈ ಸಪ್ಲೈಯರ್‌ಗಳು ನಿಮ್ಮ ಯಾವ ಬಿಲ್ ಅನ್ನೂ ರಿಪೋರ್ಟ್ ಮಾಡಿಲ್ಲ. ಅವರು GSTR-1 ಫೈಲ್ ಮಾಡದೇ ಇರಬಹುದು.",
