  "c8.formh": "ಮಾರಾಟ ನಿಮ್ಮ ಸೇವ್ ಮಾಡಿದ ಬಿಲ್ ಆಫ್ ಸಪ್ಲೈ ಮತ್ತು ಕ್ಯಾಶ್ ಮೆಮೊಗಳಿಂದ ತುಂಬಿದೆ. ವಿನಾಯಿತಿ ಮಾರಾಟವನ್ನು ಅದರ ಬಾಕ್ಸ್‌ಗೆ ಸರಿಸಿ, ಬೇರೆ ಏನಿದ್ದರೂ ಟೈಪ್ ಮಾಡಿ.",
