  "c8.r.rcm": "ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಟ್ಯಾಕ್ಸ್",
  "c8.r.int": "ಬಡ್ಡಿ",
  "c8.r.cash": "ಕ್ಯಾಶ್‌ನಲ್ಲಿ ಕಟ್ಟಬೇಕಾದ ಒಟ್ಟು ಮೊತ್ತ",
  "c8.cash": "ಕಾಂಪೊಸಿಷನ್ ಡೀಲರ್ ಇನ್‌ಪುಟ್ ಟ್ಯಾಕ್ಸ್ ಕ್ರೆಡಿಟ್ ಬಳಸುವಂತಿಲ್ಲ: ಪೂರ್ತಿ ಮೊತ್ತವನ್ನು ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಕ್ಯಾಶ್ ಲೆಡ್ಜರ್ ಮೂಲಕ ಕ್ಯಾಶ್‌ನಲ್ಲಿ ಕಟ್ಟಬೇಕು.",
  "c8.h.lim": "ಈ ವರ್ಷದ ಕಾಂಪೊಸಿಷನ್ ಮಿತಿ",
  "c8.used": "ಮಿತಿಯ {p}% ಬಳಕೆಯಾಗಿದೆ",
  "c8.used2": "ಇದುವರೆಗಿನ ಟರ್ನ್‌ಓವರ್ {a}, ಮಿತಿ {l} ರಲ್ಲಿ ({p}%).",
  "c8.w.near": "ನೀವು ಕಾಂಪೊಸಿಷನ್ ಮಿತಿಯ 80% ಕ್ಕಿಂತ ಹೆಚ್ಚು ಬಳಸಿದ್ದೀರಿ. ಮುಂಚಿತವಾಗಿ ಯೋಜಿಸಿ: ಮಿತಿ ದಾಟಿದರೆ ಸಾಮಾನ್ಯ ಸ್ಕೀಮ್‌ಗೆ ಹೋಗಬೇಕು.",
  "c8.w.over": "ಟರ್ನ್‌ಓವರ್ ಕಾಂಪೊಸಿಷನ್ ಮಿತಿಗಿಂತ ಹೆಚ್ಚಾಗಿದೆ. ಅದು ದಾಟಿದ ದಿನದಿಂದ ನೀವು ಸ್ಕೀಮ್‌ನಿಂದ ಹೊರಗಿದ್ದೀರಿ: 7 ದಿನಗಳೊಳಗೆ GST CMP-04 ಫೈಲ್ ಮಾಡಿ ಮತ್ತು ಟ್ಯಾಕ್ಸ್ ಇನ್‌ವಾಯ್ಸ್ ನೀಡಿ. ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ರನ್ನು ಕೇಳಿ.",
  "c8.w.trex": "ವ್ಯಾಪಾರಿಗಳು ಟ್ಯಾಕ್ಸ್ ಬರುವ ಮಾರಾಟದ ಮೇಲೆ ಮಾತ್ರ 1% ಕಟ್ಟುತ್ತಾರೆ, ಆದ್ದರಿಂದ ವಿನಾಯಿತಿ ಮಾರಾಟಕ್ಕೆ ಇಲ್ಲಿ ಟ್ಯಾಕ್ಸ್ ಇಲ್ಲ.",
