  "b1.tcson": "ಈ ಬಿಲ್‌ನಲ್ಲಿ TCS ತೆಗೆದುಕೊಳ್ಳಿ",
  "b1.tcsh": "ಮಾರಾಟಗಾರರು ಆದಾಯ ತೆರಿಗೆ ಸಂಗ್ರಹಿಸಬೇಕಾದ ಮಾರಾಟಗಳಿಗೆ ಮಾತ್ರ: ಆದಾಯ ತೆರಿಗೆ ಕಾಯ್ದೆ 2025 ಸೆಕ್ಷನ್ 394 (ಹಿಂದೆ ಸೆಕ್ಷನ್ 206C). ಫೈನಾನ್ಸ್ ಕಾಯ್ದೆ 2026 ನಂತರದ ರೇಟ್: ಮದ್ಯ, ತೆಂಡು ಎಲೆ, ಮರ ಅಥವಾ ಅರಣ್ಯ ಉತ್ಪನ್ನ, ಸ್ಕ್ರ್ಯಾಪ್, ಕಲ್ಲಿದ್ದಲು, ಲಿಗ್ನೈಟ್ ಅಥವಾ ಕಬ್ಬಿಣದ ಅದಿರು 2%; ₹10 ಲಕ್ಷ ಮೀರಿದ ವಾಹನ ಅಥವಾ ಅಧಿಸೂಚಿತ ವಸ್ತು 1%; ವಿದೇಶ ಟೂರ್ ಪ್ಯಾಕೇಜ್ 2%; ಪಾರ್ಕಿಂಗ್, ಟೋಲ್ ಪ್ಲಾಜಾ, ಗಣಿ 2%. 1 ರಿಂದ 5 ವಸ್ತುಗಳಿಗೆ ಖರೀದಿದಾರರು ಇದು ತಯಾರಿಕೆಗೆ, ವ್ಯಾಪಾರಕ್ಕಲ್ಲ ಎಂದು ಬರೆದು ಕೊಟ್ಟರೆ TCS ಇಲ್ಲ. ಇತರ ಸರಕಿಗೆ TCS ಇಲ್ಲ (₹50 ಲಕ್ಷದ ಹಳೆಯ ನಿಯಮ ಇಲ್ಲ).",
