  "b1.tcs_tax": "ಟ್ಯಾಕ್ಸಬಲ್ ವ್ಯಾಲ್ಯೂ (GST ಇಲ್ಲದೆ)",
  "b1.sumtcs": "TCS {v}",
  "b1.v_chg": "ಹೆಚ್ಚುವರಿ ಚಾರ್ಜ್‌ಗೆ ಹೆಸರು ಕೊಡಿ, ಉದಾ. ಬಾಡಿಗೆ.",
  "b1.v_tcs": "TCS ರೇಟ್ ಬರೆಯಿರಿ, ಅಥವಾ TCS ಟಿಕ್ ತೆಗೆಯಿರಿ.",
  "b1.v_tcs10": "ವಾಹನ ಅಥವಾ ನೋಟಿಫೈಡ್ ವಸ್ತುಗಳ ಮೇಲೆ TCS ಒಂದು ಐಟಂನ ಬೆಲೆ ₹10 ಲಕ್ಷ ಮೀರಿದರೆ ಮಾತ್ರ (ನೋಟಿಫಿಕೇಶನ್ 36/2025 ಕುರಿತ CBDT FAQ, 23 ಏಪ್ರಿಲ್ 2025). ಈ ಬಿಲ್‌ನಲ್ಲಿ ಅಂತಹ ಐಟಂ ಇಲ್ಲ. TCS ಟಿಕ್ ತೆಗೆಯಿರಿ.",
  "b1.c_tcs10g": "GST ಇಲ್ಲದೆ ಯಾವ ಐಟಂ ಕೂಡ ₹10 ಲಕ್ಷ ಮೀರಿಲ್ಲ, GST ಸೇರಿಸಿದರೆ ಮಾತ್ರ ಮೀರುತ್ತದೆ. ಆಕ್ಟ್‌ನಲ್ಲಿ \"ವ್ಯಾಲ್ಯೂ\" ಎಂದಿದೆ; ಈ ಲಿಮಿಟ್‌ನಲ್ಲಿ GST ಎಣಿಸಬೇಕೇ ಎಂದು ಯಾವ ಸರ್ಕ್ಯುಲರ್ ಕೂಡ ತೀರ್ಮಾನಿಸಿಲ್ಲ. ಈ ಬಿಲ್‌ಗೆ TCS ತೆಗೆದುಕೊಳ್ಳಬೇಕೇ?",
  "b1.tcsbh": "CBDT ಸರ್ಕ್ಯುಲರ್ 17/2020 (ಪ್ಯಾರಾ 4.6.1, ಹಳೆಯ ಸೆಕ್ಷನ್ 206C ಗಾಗಿ): TCS ಬಂದ ಮೊತ್ತದ ಮೇಲೆ GST ಸಹಿತ ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತದೆ; GST, ಡಿಸ್ಕೌಂಟ್ ಅಥವಾ ರಿಟರ್ನ್‌ಗಾಗಿ ಏನೂ ಕಡಿತವಿಲ್ಲ. ಟ್ಯಾಕ್ಸಬಲ್ ವ್ಯಾಲ್ಯೂವನ್ನು ನಿಮ್ಮ CA ಹೇಳಿದರೆ ಮಾತ್ರ ಆರಿಸಿ.",
  "b1.cntcs": "ಬಿಲ್ {no} ಮೇಲೆ {v} TCS ಇತ್ತು. ಈ ಕ್ರೆಡಿಟ್ ನೋಟ್ ಆ TCS ಅನ್ನು ಕಡಿಮೆ ಮಾಡುವುದಿಲ್ಲ: CBDT ಸರ್ಕ್ಯುಲರ್ 17/2020 (ಪ್ಯಾರಾ 4.6.1) ಪ್ರಕಾರ ಸೇಲ್ಸ್ ರಿಟರ್ನ್‌ಗೆ ಯಾವುದೇ ಅಡ್ಜಸ್ಟ್‌ಮೆಂಟ್ ಇಲ್ಲ. ಖರೀದಿದಾರರು ಈ TCS ಅನ್ನು ತಮ್ಮ ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ರಿಟರ್ನ್‌ನಲ್ಲಿ ಕ್ಲೈಮ್ ಮಾಡುತ್ತಾರೆ.",
  "b1.tcspan": "ಖರೀದಿದಾರರ PAN",
  "b1.tcspanh": "ಖರೀದಿದಾರರ GSTIN ನಿಂದ ತಾನಾಗಿ ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತದೆ. ಸರಿಯಾದ PAN ಇಲ್ಲದಿದ್ದರೆ TCS ಹೆಚ್ಚಿನ ರೇಟ್‌ನಲ್ಲಿ ಬರುತ್ತದೆ (ಸೆಕ್ಷನ್ 397(2)) ಮತ್ತು ತಯಾರಿಕೆ ಡಿಕ್ಲರೇಶನ್ ಮಾನ್ಯವಲ್ಲ.",
