  "b1.rep_p": "\"ಈ ಬಿಲ್ ಮತ್ತೆ ಮಾಡಿ\" ಜೊತೆ ಸೇವ್ ಮಾಡಿದ ಬಿಲ್‌ಗಳು. ಬೇಕಾದ ಕಾಪಿಗಳಿಗೆ ಟಿಕ್ ಮಾಡಿ ಬಟನ್ ಒತ್ತಿ; ಪ್ರತಿ ಕಾಪಿಗೆ ಮುಂದಿನ ಇನ್‌ವಾಯ್ಸ್ ನಂಬರ್ ಮತ್ತು ತೋರಿಸಿದ ದಿನಾಂಕ ಸಿಗುತ್ತದೆ. ನಿಮ್ಮ ಟ್ಯಾಪ್ ಇಲ್ಲದೆ ಏನೂ ಆಗುವುದಿಲ್ಲ.",
