  "b1.thisdev": "ಈ ಡಿವೈಸ್",
  "b1.logp": "ಯಾವುದೇ Nivesh Sahayak ಸೈಟ್‌ನಲ್ಲಿ ಬಿಸಿನೆಸ್, ಪಾರ್ಟಿ, ಐಟಂ ಅಥವಾ ಡಾಕ್ಯುಮೆಂಟ್ ಸೇರಿಸಿದಾಗ, ಬದಲಿಸಿದಾಗ, ಅಳಿಸಿದಾಗ ಅಥವಾ ರೀಸ್ಟೋರ್ ಮಾಡಿದಾಗ ದಿನಾಂಕ, ಸಮಯ, ಹೆಸರು ಮತ್ತು ಏನು ಬದಲಾಯಿತು ಎಂದು ಇಲ್ಲಿ ದಾಖಲಾಗುತ್ತದೆ. ಈ ದಾಖಲೆಗಳನ್ನು ಬದಲಿಸಲು ಅಥವಾ ತೆಗೆಯಲು ಆಗುವುದಿಲ್ಲ.",
  "b1.logrule": "1 ಏಪ್ರಿಲ್ 2023 ರಿಂದ ಕಂಪನಿಗಳು ಇಂಥ ಆಡಿಟ್ ಟ್ರೇಲ್ ಇಡುವ ಅಕೌಂಟ್ಸ್ ಸಾಫ್ಟ್‌ವೇರ್ ಬಳಸಬೇಕು (ಕಂಪನಿಗಳ (ಅಕೌಂಟ್ಸ್) ನಿಯಮಗಳು 2014, ನಿಯಮ 3(1)). ಇದು ಈ ಬ್ರೌಸರ್ ಮತ್ತು ನಿಮ್ಮ ಬ್ಯಾಕಪ್ ಫೈಲ್‌ನಲ್ಲಿ ಇರುತ್ತದೆ.",
