  "b1.h_who": "ಈ ಡಿವೈಸ್‌ನಲ್ಲಿ ಮಾಡುವ ಪ್ರತಿ ಬದಲಾವಣೆಯ ಜೊತೆ ಬದಲಾವಣೆ ದಾಖಲೆಯಲ್ಲಿ ಕಾಣುತ್ತದೆ.",
  "b1.lock": "ಈ ದಿನಾಂಕಕ್ಕಿಂತ ಮೊದಲಿನ ಡಾಕ್ಯುಮೆಂಟ್ ಲಾಕ್ ಮಾಡಿ",
  "b1.h_lock": "ಈ ದಿನಕ್ಕಿಂತ ಮೊದಲಿನ ದಿನಾಂಕದ ಡಾಕ್ಯುಮೆಂಟ್‌ಗಳನ್ನು ಯಾವ ಸೈಟ್‌ನಲ್ಲೂ ಸೇರಿಸಲು, ಬದಲಿಸಲು ಅಥವಾ ಅಳಿಸಲು ಆಗುವುದಿಲ್ಲ (ಪೇಮೆಂಟ್ ಬಂತು ಎಂದು ಗುರುತಿಸುವುದು ನಡೆಯುತ್ತದೆ). GST ರಿಟರ್ನ್ ಸಲ್ಲಿಸಿದ ಅಥವಾ ಲೆಕ್ಕ ಮುಚ್ಚಿದ ನಂತರ ಬಳಸಿ.",
  "b1.lockc": "{d} ಕ್ಕಿಂತ ಮೊದಲಿನ ದಿನಾಂಕದ ಎಲ್ಲಾ ಡಾಕ್ಯುಮೆಂಟ್ ಲಾಕ್ ಮಾಡಬೇಕೇ? ಈ ದಿನಾಂಕ ತೆಗೆಯುವವರೆಗೆ ಬದಲಿಸಲು ಆಗುವುದಿಲ್ಲ.",
  "b1.unlockc": "ಹಳೆಯ ಡಾಕ್ಯುಮೆಂಟ್‌ಗಳನ್ನು ಮತ್ತೆ ಬದಲಿಸಲು ಅನ್‌ಲಾಕ್ ಮಾಡಬೇಕೇ?",
  "b1.locked": "ಲಾಕ್ ಆಗಿದೆ: {d} ಕ್ಕಿಂತ ಮೊದಲಿನ ದಿನಾಂಕದ ಡಾಕ್ಯುಮೆಂಟ್ ಬದಲಿಸಲು ಆಗುವುದಿಲ್ಲ. ಮೊದಲು ಸೆಟ್ಟಿಂಗ್ಸ್ ಮತ್ತು ಸೇವ್ ಡೇಟಾ › ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಲಾಕ್ ದಿನಾಂಕ ತೆಗೆಯಿರಿ.",
