  "b2.sales": "ಮಾರಿದ ಮೊತ್ತ",
  "b2.dep": "ಸವಕಳಿ",
  "b2.closewdv": "ಕ್ಲೋಸಿಂಗ್ WDV",
  "b2.gain": "ಲಾಭ {a}: ಅಕೌಂಟೆಂಟ್‌ರನ್ನು ಕೇಳಿ",
  "b2.farules": "ಸವಕಳಿ ಹೇಗೆ ಲೆಕ್ಕ ಹಾಕಲಾಗುತ್ತದೆ",
  "b2.farule1": "ಖಾತೆಯ ಸವಕಳಿ ಕಂಪನಿಗಳ ಕಾಯ್ದೆ, 2013 ರ ಶೆಡ್ಯೂಲ್ II ಪ್ರಕಾರ: ಪ್ರತಿ ವಿಧದ ಅಸೆಟ್‌ಗೆ ಬಳಕೆ ಅವಧಿ ಇದೆ (ಉದಾ. ಕಂಪ್ಯೂಟರ್ 3 ವರ್ಷ, ಫರ್ನಿಚರ್ 10 ವರ್ಷ, ಪ್ಲಾಂಟ್ ಮತ್ತು ಮೆಷಿನರಿ 15 ವರ್ಷ, ಕಾರು 8 ವರ್ಷ), ಉಳಿಕೆ ಮೌಲ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಬೆಲೆಯ 5% ಮೀರುವುದಿಲ್ಲ, ವರ್ಷದ ಮಧ್ಯೆ ಸೇರಿಸಿದ ಅಥವಾ ಮಾರಿದ ಅಸೆಟ್‌ಗೆ ಬಳಸಿದ ದಿನಗಳಿಗೆ ಮಾತ್ರ ಸವಕಳಿ. ಸ್ಟ್ರೇಟ್ ಲೈನ್ (SLM: ಪ್ರತಿ ವರ್ಷ ಅದೇ ಮೊತ್ತ) ಅಥವಾ ರಿಟನ್ ಡೌನ್ ವ್ಯಾಲ್ಯೂ (WDV: ಉಳಿದ ಮೊತ್ತದ ಮೇಲೆ ನಿಗದಿತ ರೇಟ್) ಆರಿಸಿ. ಪ್ರೊಪ್ರೈಟರ್ ಮತ್ತು ಫರ್ಮ್‌ಗಳು ಹೆಚ್ಚಾಗಿ ಇದೇ ವಿಧಾನ ಬಳಸುತ್ತವೆ; ತೀರ್ಮಾನ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ರದು.",
  "b2.farule2": "ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ಸವಕಳಿ ಪ್ರತಿ ಬ್ಲಾಕ್‌ಗೆ ಬೇರೆಯಾಗಿ ಲೆಕ್ಕ: ಬ್ಲಾಕ್ ರೇಟ್‌ನಲ್ಲಿ ರಿಟನ್ ಡೌನ್ ವ್ಯಾಲ್ಯೂ (ಉದಾ. ಪ್ಲಾಂಟ್ ಮತ್ತು ಮೆಷಿನರಿ 15%, ಫರ್ನಿಚರ್ 10%, ಕಂಪ್ಯೂಟರ್ 40%), ವರ್ಷದಲ್ಲಿ 180 ದಿನಕ್ಕಿಂತ ಕಡಿಮೆ ಬಳಸಿದ ಅಸೆಟ್‌ಗೆ ಅರ್ಧ ರೇಟ್, ಮಾರಾಟದ ಹಣ ಬ್ಲಾಕ್‌ನಿಂದ ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಇದು ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ರಿಟರ್ನ್‌ಗೆ ಮಾತ್ರ, ಖಾತೆಗೆ ಎಂದೂ ಹಾಕುವುದಿಲ್ಲ. ತುಂಬಿದ ರೇಟ್‌ಗಳು ಸಾಮಾನ್ಯ ಬ್ಲಾಕ್ ರೇಟ್‌ಗಳು: ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ರೊಂದಿಗೆ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ, ವಿಶೇಷವಾಗಿ 1 ಏಪ್ರಿಲ್ 2026 ರಿಂದ ಇನ್‌ಕಮ್-ಟ್ಯಾಕ್ಸ್ ಕಾಯ್ದೆ, 2025 ಅಡಿಯ ವರ್ಷಗಳಿಗೆ.",
  "b2.farule3": "ನೀವು 'ಸವಕಳಿ ಹಾಕಿ' ಒತ್ತಿದಾಗ ಮಾತ್ರ ಸವಕಳಿ ಖಾತೆಗೆ ಹೋಗುತ್ತದೆ: ವರ್ಷದ ಕೊನೆಯ ದಿನದ (ಅಥವಾ ವರ್ಷದ ಮಧ್ಯೆ ಇಂದಿನ) ಜರ್ನಲ್ ಎಂಟ್ರಿ ಸವಕಳಿಯನ್ನು ಡೆಬಿಟ್ ಮಾಡಿ ಪ್ರತಿ ಅಸೆಟ್ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ. ಆಮೇಲೆ ಅಸೆಟ್ ಬದಲಿಸಿದರೆ ಮತ್ತೆ ಹಾಕಿ, ವ್ಯತ್ಯಾಸ ಮಾತ್ರ ಸೇರುತ್ತದೆ.",
