  "b2.ck_neg": "{n} ಐಟಂಗಳ ಸ್ಟಾಕ್ ಸೊನ್ನೆಗಿಂತ ಕಡಿಮೆ ಕಾಣುತ್ತಿದೆ: ಬಹುಶಃ ಯಾವುದೋ ಖರೀದಿ ಅಥವಾ ಓಪನಿಂಗ್ ಸ್ಟಾಕ್ ಬಿಟ್ಟುಹೋಗಿದೆ.",
