  "b2.nextyear": "FY {fy} ಗೆ",
  "b2.carryh": "ಈ ಡೇಟಾ ಹೋಮ್‌ನಲ್ಲಿ ಏನನ್ನೂ ಸ್ಥಳಾಂತರಿಸಬೇಕಿಲ್ಲ: ಪಾರ್ಟಿ ಬ್ಯಾಲೆನ್ಸ್, ಕ್ಯಾಶ್, ಬ್ಯಾಂಕ್ ಮತ್ತು ಸ್ಟಾಕ್ ತಾನಾಗಿಯೇ ಹೊಸ ವರ್ಷಕ್ಕೆ ಮುಂದುವರಿಯುತ್ತವೆ, ಏಕೆಂದರೆ ಆ್ಯಪ್ ಪ್ರತಿ ಸೇವ್ ಆದ ದಾಖಲೆಯಿಂದ ಲೆಕ್ಕ ಹಾಕುತ್ತದೆ.",
  "b2.numh": "ಪ್ರತಿ ಫೈನಾನ್ಶಿಯಲ್ ಇಯರ್‌ನಲ್ಲಿ ಡಾಕ್ಯುಮೆಂಟ್ ನಂಬರ್‌ಗಳು ಮತ್ತೆ 001 ರಿಂದ ಶುರು (ಉದಾ. INV/27-28/001), ಅದೇ ಪ್ರಿಫಿಕ್ಸ್‌ನೊಂದಿಗೆ, ಹಾಗಾಗಿ ಹೊಸ ವರ್ಷಕ್ಕೆ ಏನೂ ಬದಲಿಸಬೇಕಿಲ್ಲ.",
  "b2.closet": "ವರ್ಷ ಮುಚ್ಚಿ",
  "b2.closeh": "ವರ್ಷ ಮುಚ್ಚಿದರೆ ಅದು ಓದಲು ಮಾತ್ರ: ಆ್ಯಪ್ ಮತ್ತು ಪ್ರತಿ ಡಾಕ್ಯುಮೆಂಟ್ ಮೇಕರ್ ಅದರೊಳಗಿನ ದಿನಾಂಕದ ಯಾವುದನ್ನೂ ಸೇವ್, ಬದಲು ಅಥವಾ ಡಿಲೀಟ್ ಮಾಡಲು ಬಿಡುವುದಿಲ್ಲ. ಯಾವಾಗ ಬೇಕಾದರೂ ಇಲ್ಲಿ ಮತ್ತೆ ತೆರೆಯಬಹುದು.",
