  "b2.newfile": "ಹೊಸ ವರ್ಷವನ್ನು ಹೊಸ ಡೇಟಾ ಫೈಲ್‌ನಲ್ಲಿ ಆರಂಭಿಸಿ",
  "b2.newfileh": "ಹೊಸ ಬ್ರೌಸರ್‌ಗೆ ಹೋಗುತ್ತಿದ್ದೀರಾ ಅಥವಾ ಹೊಸದಾಗಿ ಶುರು ಮಾಡುತ್ತಿದ್ದೀರಾ? ಈ ಫೈಲ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಬಿಸಿನೆಸ್, ಗ್ರಾಹಕರು, ಸಪ್ಲೈಯರ್‌ಗಳು, ಐಟಂಗಳು ಮತ್ತು 1 ಏಪ್ರಿಲ್‌ನ ಓಪನಿಂಗ್ ಬ್ಯಾಲೆನ್ಸ್ ಇವೆ: ಪ್ರತಿ ಪಾರ್ಟಿಯ ಬ್ಯಾಲೆನ್ಸ್, ಕ್ಯಾಶ್, ಬ್ಯಾಂಕ್, ಸರಾಸರಿ ಬೆಲೆಯಲ್ಲಿ ಸ್ಟಾಕ್, ಮತ್ತು ಫಿಕ್ಸ್‌ಡ್ ಅಸೆಟ್ಸ್, ಸಾಲ, GST, TDS ಮತ್ತು ಬಂಡವಾಳಕ್ಕೆ ಒಂದು ಜರ್ನಲ್ ಎಂಟ್ರಿ (ವರ್ಷದ ಲಾಭ ಬಂಡವಾಳದಲ್ಲಿದೆ). ಅಲ್ಲಿ My data, ಬ್ಯಾಕಪ್‌ನಲ್ಲಿ ರಿಸ್ಟೋರ್ ಮಾಡಿ.",
  "b2.cfdl": "FY {fy} ಓಪನಿಂಗ್ ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ",
  "b2.cfdone": "{n} ಓಪನಿಂಗ್ ದಾಖಲೆಗಳೊಂದಿಗೆ ಫೈಲ್ ಸೇವ್ ಆಯಿತು.",
  "b2.gd": "ಗೋಡೌನ್ ಮತ್ತು ಸ್ಟಾಕ್ ಟ್ರಾನ್ಸ್‌ಫರ್",
  "b2.gdh": "ಪ್ರತಿ ಗೋಡೌನ್‌ನ ಸ್ಟಾಕ್ ಬಿಲ್‌ಗಳಲ್ಲಿ ಆರಿಸಿದ ಗೋಡೌನ್ (ಹೆಚ್ಚಿನ ವಿವರ) ಮತ್ತು ಟ್ರಾನ್ಸ್‌ಫರ್‌ಗಳಿಂದ ಬರುತ್ತದೆ. ಗೋಡೌನ್ ಇಲ್ಲದ ಬಿಲ್‌ಗಳು ಮೇನ್ ಗೋಡೌನ್ ಎಂದು ಪರಿಗಣಿಸಲ್ಪಡುತ್ತವೆ. ಟ್ರಾನ್ಸ್‌ಫರ್‌ನಿಂದ ಬಿಸಿನೆಸ್‌ನ ಒಟ್ಟು ಸ್ಟಾಕ್ ಬದಲಾಗುವುದಿಲ್ಲ.",
