  "b3.gd.t": "Google Drive ಸಿಂಕ್",
  "b3.gd.p": "ನಿಮ್ಮ ಸ್ವಂತ Google Drive ಮೂಲಕ ಫೋನ್ ಮತ್ತು ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಡೇಟಾ ಒಂದೇ ರೀತಿ ಇಡಿ. ಈ ಆ್ಯಪ್ ಅಲ್ಲಿ ಮಾಡುವ ಒಂದೇ ಫೈಲ್ ಅನ್ನು ಮಾತ್ರ ನಾವು ನೋಡಬಹುದು, ನಮಗೆ ಏನೂ ಬರುವುದಿಲ್ಲ.",
