  "b3.gd.clashp": "ಅತಿ ಹೊಸ ಬದಲಾವಣೆಯನ್ನು ಇಡಲಾಗಿದೆ. ಇವು ಬೇರೆ ಕಾಪಿಗಳು: ಯಾವುದಾದರೂ ಸರಿಯಾಗಿದ್ದರೆ ಅದನ್ನು ಮರಳಿ ತನ್ನಿ.",
