  "b3.gd.st.biz": "ಬಿಸಿನೆಸ್",
  "b3.gd.st.party": "ಪಾರ್ಟಿ",
  "b3.gd.st.item": "ಐಟಂ",
  "b3.gd.st.doc": "ಡಾಕ್ಯುಮೆಂಟ್",
  "b3.gd.st.meta": "ಸೆಟ್ಟಿಂಗ್",
  "hp.btn": "ಸಹಾಯ: {what}",
  "hp.biz": "ಮೇಲೆ ಪ್ರಿಂಟ್ ಆಗುವ ನಿಮ್ಮ ಬಿಸಿನೆಸ್ ವಿವರಗಳು. ಸಲಹೆಗಳಿಂದ ಸೇವ್ ಮಾಡಿದ ಬಿಸಿನೆಸ್ ಆಯ್ಕೆಮಾಡಿ, ಅಥವಾ ಒಮ್ಮೆ ಬರೆಯಿರಿ, ಮುಂದಿನ ಬಾರಿಗೆ ಸೇವ್ ಆಗುತ್ತದೆ.",
  "hp.details": "ನಂಬರ್ ಮತ್ತು ದಿನಾಂಕ. ಪ್ರತಿ ಫೈನಾನ್ಶಿಯಲ್ ಇಯರ್‌ನಲ್ಲಿ ನಂಬರ್ ತಾನಾಗಿಯೇ ಹೆಚ್ಚುತ್ತದೆ; ನಿಮ್ಮದೇ ಸೀರೀಸ್ ಇದ್ದರೆ ಬದಲಾಯಿಸಬಹುದು.",
  "hp.billto": "ನೀವು ಯಾರಿಗೆ ಬಿಲ್ ಕೊಡುತ್ತಿದ್ದೀರೋ ಅವರು. ಹೆಸರು ಬರೆಯಲು ಶುರುಮಾಡಿ ಸೇವ್ ಮಾಡಿದ ಕಸ್ಟಮರ್ ಆಯ್ಕೆಮಾಡಿ, ಅಥವಾ ಹೊಸದು ಬರೆಯಿರಿ. GSTIN ನಿಂದ ಸ್ಟೇಟ್ ತುಂಬುತ್ತದೆ; ಸ್ಟೇಟ್ CGST+SGST ಅಥವಾ IGST ಎಂದು ತೀರ್ಮಾನಿಸುತ್ತದೆ.",
  "hp.vendor": "ನೀವು ಆರ್ಡರ್ ಮಾಡುತ್ತಿರುವ ಸಪ್ಲೈಯರ್. ಸೇವ್ ಮಾಡಿದ ಸಪ್ಲೈಯರ್ ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ ಹೊಸದು ಬರೆಯಿರಿ.",
  "hp.supplier": "ನೋಂದಣಿ ಇಲ್ಲದ ಯಾರಿಂದ ಖರೀದಿಸಿದಿರೋ ಅವರು. ಈ ಸೆಲ್ಫ್ ಇನ್‌ವಾಯ್ಸ್‌ನಲ್ಲಿ GST ಅನ್ನು ರಿವರ್ಸ್ ಚಾರ್ಜ್‌ನಲ್ಲಿ ನೀವೇ ಕಟ್ಟುತ್ತೀರಿ.",
  "hp.consignee": "ಸರಕು ಖರೀದಿದಾರರ ಹೊರತು ಬೇರೆ ಜಾಗ ಅಥವಾ ವ್ಯಕ್ತಿಗೆ ಹೋಗುವಾಗ ಮಾತ್ರ ತುಂಬಿ.",
  "hp.items": "ಪ್ರತಿ ಐಟಂ ಅಥವಾ ಸರ್ವಿಸ್‌ಗೆ ಒಂದು ಸಾಲು. ಸೇವ್ ಮಾಡಿದ ಐಟಂ ಆಯ್ಕೆಮಾಡಿದರೆ ರೇಟ್, HSN, GST ತುಂಬುತ್ತವೆ, ಅಥವಾ ಹೊಸದು ಬರೆಯಿರಿ. ಪ್ರಮಾಣ × ರೇಟ್‌ನಿಂದ ಡಿಸ್ಕೌಂಟ್ ಕಳೆದರೆ ಟ್ಯಾಕ್ಸಬಲ್ ಮೌಲ್ಯ.",
  "hp.notes": "ಷರತ್ತುಗಳು, ಬ್ಯಾಂಕ್ ವಿವರಗಳು ಮತ್ತು ಪ್ರಿಂಟ್ ಪುಟದ ರೂಪ. ಮುಂದಿನ ಬಾರಿಗೆ ಡೀಫಾಲ್ಟ್ ಆಗಿ ಸೇವ್ ಆಗುತ್ತದೆ.",
  "hp.einv": "ಇ-ಇನ್‌ವಾಯ್ಸ್ ಅಥವಾ ಇ-ವೇ ಬಿಲ್ ಕಡ್ಡಾಯ ಇರುವ ಬಿಸಿನೆಸ್‌ಗಳಿಗೆ: ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ಸರ್ಕಾರಿ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಲಾಗಿನ್‌ನಿಂದ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಉತ್ತರವನ್ನು ಇಲ್ಲಿ ಲೋಡ್ ಮಾಡಿ.",
  "hp.exp": "ರಫ್ತಿಗೆ: ಶಿಪ್ಪಿಂಗ್ ಬಿಲ್, ಪೋರ್ಟ್ ಮತ್ತು ಕರೆನ್ಸಿ. ರಫ್ತು ಜೀರೋ-ರೇಟೆಡ್: LUT ಇದ್ದರೆ GST ಇಲ್ಲ; ಇಲ್ಲದಿದ್ದರೆ IGST ಕಟ್ಟಿ ರೀಫಂಡ್ ಸಿಗುತ್ತದೆ.",
  "hp.s.from": "ನಿಮಗೆ ಹಣ ಕೊಟ್ಟವರು. ಸೇವ್ ಮಾಡಿದ ಕಸ್ಟಮರ್ ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ ಹೆಸರು ಬರೆಯಿರಿ.",
  "hp.s.pay": "ಮೊತ್ತ, ದಿನಾಂಕ ಮತ್ತು ಹೇಗೆ ಕೊಟ್ಟರು. ಕಾನೂನು ಮಿತಿಗಿಂತ ಹೆಚ್ಚು ಕ್ಯಾಶ್‌ಗೆ ಎಚ್ಚರಿಕೆ ಬರುತ್ತದೆ.",
  "hp.s.to": "ನೀವು ಹಣ ಕೊಟ್ಟವರು. ಸೇವ್ ಮಾಡಿದ ಸಪ್ಲೈಯರ್ ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ ಹೆಸರು ಬರೆಯಿರಿ.",
  "hp.s.lines": "ಹಣ ಯಾವುದಕ್ಕಾಗಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು ಸಾಲು (ಉದಾ: ಬಾಡಿಗೆ, ರಿಪೇರಿ, ಸಾಗಣೆ ಬಾಡಿಗೆ).",
  "hp.s.tdsrcm": "ಈ ಪೇಮೆಂಟ್‌ನಿಂದ TDS ಕಡಿತ ಮಾಡಿದ್ದರೆ, ಅಥವಾ ರಿವರ್ಸ್ ಚಾರ್ಜ್‌ನಲ್ಲಿ GST ನೀವು ಕಟ್ಟಬೇಕಿದ್ದರೆ ತುಂಬಿ.",
  "hp.s.sign": "ಕೊಟ್ಟವರು, ಪಡೆದವರು ಮತ್ತು ಅನುಮೋದಿಸಿದವರ ಹೆಸರು. ಕೈಯಿಂದ ಸಹಿ ಮಾಡಬೇಕಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ.",
