  "hp.s.ded": "PF, ESI, ವೃತ್ತಿ ತೆರಿಗೆ, TDS ಮತ್ತು ಇತರ ಕಡಿತಗಳು. ಬಟನ್ ಇವನ್ನು ತಾನಾಗಿ ಲೆಕ್ಕ ಹಾಕಬಲ್ಲದು.",
